// ============================================================================
//  Optional configurator page served by the ESP itself (`configurator: true`).
//
//    GET /remeha            the configurator (gzip-compressed HTML, see
//                           configurator_page.h, generated by tools/build_configurator.py)
//    GET /remeha/scan       ask the hub to scan the appliance (read-only: id +
//                           menu descriptor 0x502B); returns the status JSON
//    GET /remeha/data.json  status and, when done, the scan result
//
//  The handler runs in the HTTP server task: it never talks BLE itself, it only
//  sets a flag on the hub and copies the JSON the hub prepares, under a mutex.
// ============================================================================
#pragma once
#include "esphome/core/defines.h"
#if defined(USE_ESP32) && defined(USE_REMEHA_CONFIGURATOR)
#include "esphome/core/component.h"
#include "esphome/components/web_server_base/web_server_base.h"
#include "remeha_ble.h"

namespace esphome {
namespace remeha_ble {

class RemehaConfigurator : public AsyncWebHandler, public Component {
 public:
  RemehaConfigurator(web_server_base::WebServerBase *base, RemehaBle *hub) : base_(base), hub_(hub) {}
  void setup() override;
  float get_setup_priority() const override { return setup_priority::WIFI - 1.0f; }  // after the web server
  bool canHandle(AsyncWebServerRequest *request) const override;
  void handleRequest(AsyncWebServerRequest *request) override;

 protected:
  web_server_base::WebServerBase *base_;
  RemehaBle *hub_;
};

}  // namespace remeha_ble
}  // namespace esphome
#endif
